const quiz=q=>({type:'quiz',minutes:9,xp:430+(q.chapter-15)*35,coins:165+(q.chapter-15)*15,buildsOn:foundations[q.chapter],...q});
const check=(fn,body)=>`f=scope.get("${fn}")\nassert callable(f), "Define ${fn}."\n${body}`;
const giniHelper='def gini(labels):\n    if not labels:\n        return 0.0\n    counts = {}\n    for label in labels:\n        counts[label] = counts.get(label, 0) + 1\n    return 1 - sum((n / len(labels)) ** 2 for n in counts.values())\n';
export const frontierQuests = [
code({id:'streaming-batches',chapter:15,title:'The mill that never stops',subtitle:'Yield batches without loading the whole stream',
lesson:['Beyond the academy, the paper mill receives a stream of orders. An iterable might be a list, a generator, or a source that cannot fit in memory. Calling list(source) eagerly consumes everything.', 'A generator function uses yield to hand out one result, then pauses with its local state intact. next(generator) resumes it. Build one batch, yield it, and replace it with a new list. This uses O(batch size) extra memory.', 'Do not reuse and clear the same yielded list: the caller still holds that object. Validate the batch size; errors inside a generator occur when it is advanced, not necessarily when it is created.'],
example:'def pairs(source):\n    batch = []\n    for item in source:\n        batch.append(item)\n        if len(batch) == 2:\n            yield batch\n            batch = []\n    if batch:\n        yield batch',
task:'Write batches(source, size), a generator yielding lists of at most size items in order. Keep a shorter final batch, emit nothing for empty input, and raise ValueError for size <= 0. Do not consume any item beyond the batch requested by next(). size is an integer.',
starter:'def batches(source, size):\n    # Validate, collect, yield, then start a fresh batch.\n    pass',
solution:'def batches(source, size):\n    if size <= 0:\n        raise ValueError("Positive batch size required")\n    batch = []\n    for item in source:\n        batch.append(item)\n        if len(batch) == size:\n            yield batch\n            batch = []\n    if batch:\n        yield batch',
checks:check('batches','import types\ng=f(iter(range(5)),2)\nassert isinstance(g,types.GeneratorType), "Use yield to create a generator."\nassert list(g)==[[0,1],[2,3],[4]]\nassert list(f([],3))==[]\nassert list(f([0,False,None],1))==[[0],[False],[None]]\nseen=[]\ndef source():\n    for i in range(6):\n        seen.append(i)\n        yield i\ng=f(source(),2)\nassert seen==[]\na=next(g)\nassert a==[0,1] and seen==[0,1], "Read only the requested batch."\nb=next(g)\nassert a==[0,1] and b==[2,3] and a is not b, "Yield independent lists."\nfor n in [0,-1]:\n    try: list(f([1],n))\n    except ValueError: pass\n    else: raise AssertionError("Reject a nonpositive size.")'),
hint:'After yielding a full batch, assign batch = [] rather than clearing the old list. Yield leftovers after the loop.',takeaway:'Lazy generators control when work happens and keep memory bounded.'}),
quiz({id:'context-lantern',chapter:15,title:'Close the mill’s ledger',subtitle:'Context managers and dependable cleanup',
lesson:['A context manager defines how to enter and leave a managed block. with open(...) as ledger closes the file when the block exits, including if an exception is raised.', 'Cleanup and error handling are different. The file context manager closes the file but does not normally suppress exceptions. A surrounding try/except can decide how to handle an error. The same pattern can manage locks or temporary resources.'],
example:'try:\n    with open("orders.txt") as ledger:\n        value = int(ledger.readline())\nexcept ValueError:\n    print("The first line was not a whole number.")',
task:'The first line contains "not a number", so int(...) raises ValueError. What happens in this example?',options:['The file stays open because the block did not finish.','The file closes, and ValueError reaches the surrounding except block.','with converts the text to zero automatically.','with prevents every error in its block.'],answer:1,
explanations:['The file context manager performs cleanup even on this exceptional exit.','Correct. Cleanup happens as the block exits; the surrounding handler deals with the error.','Context managers do not repair invalid numeric text.','The exception still occurs; with manages the resource lifetime.'],hint:'Separate who closes the file from who handles the failed conversion.',takeaway:'Use resource management to guarantee cleanup; handle failures separately.'}),
code({id:'indexed-join',chapter:15,title:'Two ledgers, one delivery',subtitle:'Join records with an index',
lesson:['Orders name a customer ID; a second ledger holds customer names. A relational join connects records by a shared key. Repeatedly scanning all customers for every order takes O(orders × customers) work.', 'Build a dictionary index once, then look up each order’s customer. Average-case dictionary access is constant time, so this approach costs O(customers + orders) plus output size. Here customer IDs are unique: one customer may have many orders.', 'We use an inner join: omit orders whose customer ID has no match. A left join would instead keep them with an explicit missing value. Choosing the join type changes which records survive.'],
example:'names = {row["id"]: row["name"] for row in customers}\n# Later: names[customer_id] looks up one customer.',
task:'Write join_orders(orders, customers). Customers have unique id and name; orders have id and customer_id. Return {"order_id": ..., "name": ...} records for matched orders in their original order. Preserve repeated orders and leave inputs unchanged. Omit unmatched orders. Build a dictionary index rather than scanning customers for each order.',
starter:'def join_orders(orders, customers):\n    # Build the index, then visit each order.\n    return []',
solution:'def join_orders(orders, customers):\n    names = {c["id"]: c["name"] for c in customers}\n    return [{"order_id": o["id"], "name": names[o["customer_id"]]} for o in orders if o["customer_id"] in names]',
checks:check('join_orders','import copy\nc=[{"id":0,"name":""},{"id":2,"name":"Nell"}]\no=[{"id":"b","customer_id":2},{"id":"a","customer_id":0},{"id":"b","customer_id":2},{"id":"x","customer_id":9}]\nbefore=copy.deepcopy((o,c))\nassert f(o,c)==[{"order_id":"b","name":"Nell"},{"order_id":"a","name":""},{"order_id":"b","name":"Nell"}], "Keep order and duplicates; match by ID, not name truthiness."\nassert (o,c)==before\nassert f([],c)==[] and f(o,[])==[]\nclass Ledger(list):\n    visits=0\n    def __iter__(self):\n        for row in super().__iter__():\n            self.visits += 1\n            yield row\nc=Ledger({"id":i,"name":str(i)} for i in range(100))\no=[{"id":i,"customer_id":i} for i in range(100)]\nassert len(f(o,c))==100 and c.visits<=200, "Index customers once instead of repeatedly scanning the ledger."'),
hint:'Check membership with customer_id in names. An empty customer name still represents a valid match.',takeaway:'Indexing avoids repeated scans; join rules determine which data is retained.'}),
code({id:'rolling-window',chapter:15,title:'The river’s moving window',subtitle:'Update a running sum in linear time',
lesson:['The mill monitors the most recent w river readings. A rolling mean smooths local variation while retaining a time sequence. This differs from averaging the entire history.', 'For adjacent windows, most readings are shared. Add the incoming reading and subtract the outgoing one from a running total. After the first full window, each update takes constant work: O(n) overall.', 'A trailing window uses only the present and past. A centered window includes later observations and is unsuitable as a real-time feature unless those values are available. Smoothing also delays rapid changes.'],
example:'values = [2, 4, 8]\n# width 2: first mean is 3; next is 6.\n# Update the sum: (2 + 4) + 8 - 2 = 12.',
task:'Write rolling_mean(values, width) using a running total. Return means of FULL trailing windows; if width exceeds the list length return []. Raise ValueError for width <= 0. width is an integer. Do not modify values.',
starter:'def rolling_mean(values, width):\n    total = 0\n    result = []\n    # Add the new value; remove the one leaving the window.\n    return result',
solution:'def rolling_mean(values, width):\n    if width <= 0:\n        raise ValueError("Positive width required")\n    total = 0\n    result = []\n    for i, value in enumerate(values):\n        total += value\n        if i >= width:\n            total -= values[i - width]\n        if i >= width - 1:\n            result.append(total / width)\n    return result',
checks:check('rolling_mean','for xs,w,want in [([2,4,8],2,[3,6]),([0,-2,4],1,[0,-2,4]),([1,2],3,[]),([],2,[]),([1,3,8,0],3,[4,11/3])]:\n    before=xs.copy();out=f(xs,w)\n    assert len(out)==len(want) and all(abs(a-b)<1e-9 for a,b in zip(out,want)), "Emit only complete trailing windows."\n    assert xs==before\nfor w in [0,-2]:\n    try: f([1],w)\n    except ValueError: pass\n    else: raise AssertionError("Reject invalid width.")\nclass Counted(list):\n    work=0\n    def __getitem__(self,k):\n        self.work += len(range(*k.indices(len(self)))) if isinstance(k,slice) else 1\n        return super().__getitem__(k)\nx=Counted(range(2000));out=f(x,1000)\nassert len(out)==1001 and x.work<=10000, "Reuse a running total instead of copying each whole window."'),
hint:'At index i >= width, the departing item is values[i-width]. The first full window ends at width-1.',takeaway:'Reuse work between overlapping windows, and respect the direction of time.'}),
code({id:'breadth-first-path',chapter:16,title:'The crossing with many paths',subtitle:'Breadth-first search on an unweighted graph',
lesson:['The crossing is a graph: places are nodes and paths are edges. Breadth-first search (BFS) explores one distance layer at a time. With equal-cost edges, the first route found uses the fewest edges.', 'Use a queue: append new nodes on the right and popleft from collections.deque. Mark a node visited when you enqueue it, so cycles do not keep adding it.', 'Store a parent for each discovered node. When the goal is reached, follow parents backward and reverse that list. With adjacency lists, BFS takes O(V+E) time; it does not minimize distance when edges have different costs.'],
example:'from collections import deque\nqueue = deque(["mill"])\nplace = queue.popleft()\nqueue.append("bridge")',
task:'Write shortest_path(graph, start, goal). graph maps string nodes to ordered lists of neighbours; missing keys have no outgoing edges. Return a fewest-edge path including start and goal, choosing first discovery in neighbour order. Return None if unreachable, or [start] when start == goal. Handle cycles without modifying graph.',
starter:'from collections import deque\n\ndef shortest_path(graph, start, goal):\n    # Queue, parents, then reconstruct the path.\n    return None',
solution:'from collections import deque\n\ndef shortest_path(graph, start, goal):\n    queue = deque([start])\n    parent = {start: None}\n    while queue:\n        node = queue.popleft()\n        if node == goal:\n            path = []\n            while node is not None:\n                path.append(node)\n                node = parent[node]\n            return path[::-1]\n        for nxt in graph.get(node, []):\n            if nxt not in parent:\n                parent[nxt] = node\n                queue.append(nxt)\n    return None',
checks:check('shortest_path','import copy\ng={"A":["B","C"],"B":["D"],"C":["G","A"],"D":["E"],"E":["G"],"G":[]};before=copy.deepcopy(g)\nassert f(g,"A","G")==["A","C","G"], "Explore by distance layers, not one entire branch."\nassert f(g,"G","A") is None\nassert f({},"A","A")==["A"]\nassert f({"A":["B","C"],"B":["G"],"C":["G"]},"A","G")==["A","B","G"]\nassert g==before'),
hint:'The parent dictionary can also be your visited set. Reconstruct only after finding the goal.',takeaway:'BFS guarantees shortest edge-count paths when every edge costs the same.'}),
code({id:'weighted-route',chapter:16,title:'The long road that costs less',subtitle:'Dijkstra’s algorithm and relaxation',
lesson:['A steep shortcut can cost more effort than several easy paths. Dijkstra’s algorithm tracks the cheapest known cost to each node and expands the lowest-cost pending node first.', 'heapq stores a min-heap of (cost, node) pairs. Relax an edge by testing whether cost + edge_weight improves the known cost. Push improvements; older heap entries can remain, so skip entries whose cost no longer matches the best known value.', 'The guarantee needs nonnegative edge weights. This exercise rejects any negative edge before searching. A node first seen through an expensive edge may still receive a cheaper route later; discovery alone does not finalize its distance.'],
example:'import heapq\nfrontier = [(0, "mill")]\nheapq.heappush(frontier, (3, "bridge"))\ncost, node = heapq.heappop(frontier)',
task:'Write cheapest_cost(graph, start, goal). graph maps strings to lists of (neighbour, nonnegative weight). Return the least total cost, None if unreachable, and 0 when start == goal. Reject any negative edge anywhere with ValueError. Missing keys have no outgoing edges.',
starter:'import heapq\n\ndef cheapest_cost(graph, start, goal):\n    # Validate weights, then repeatedly relax the cheapest frontier.\n    return None',
solution:'import heapq\n\ndef cheapest_cost(graph, start, goal):\n    if any(w < 0 for edges in graph.values() for _, w in edges):\n        raise ValueError("Nonnegative weights required")\n    best = {start: 0}\n    heap = [(0, start)]\n    while heap:\n        cost, node = heapq.heappop(heap)\n        if cost != best[node]:\n            continue\n        if node == goal:\n            return cost\n        for nxt, weight in graph.get(node, []):\n            candidate = cost + weight\n            if candidate < best.get(nxt, float("inf")):\n                best[nxt] = candidate\n                heapq.heappush(heap, (candidate, nxt))\n    return None',
checks:check('cheapest_cost','import copy\ng={"A":[("G",9),("B",1)],"B":[("G",2),("A",0)]};before=copy.deepcopy(g)\nassert f(g,"A","G")==3, "Fewest edges need not have lowest cost."\nassert f({"A":[("B",7),("C",1)],"C":[("B",1)],"B":[("G",1)]},"A","G")==3\nassert f({"A":[("B",0)],"B":[("A",0)]},"A","G") is None\nassert f({},"X","X")==0\nassert g==before\ntry: f({"elsewhere":[("Z",-1)]},"A","A")\nexcept ValueError: pass\nelse: raise AssertionError("Validate even disconnected edges.")'),
hint:'Check the whole graph for negative weights first. A better route replaces best[nxt] even if nxt was seen before.',takeaway:'Cost-aware search repeatedly improves distances; BFS and Dijkstra solve different path problems.'}),
quiz({id:'search-complexity',chapter:16,title:'Count the crossings, not the seconds',subtitle:'Reason about algorithm growth',
lesson:['Big-O describes how work grows with input size, not an exact stopwatch time. With adjacency lists, BFS visits each reachable node once and examines each outgoing edge once: O(V+E).', 'An adjacency matrix instead scans V possible neighbours for each node, giving O(V²) traversal work. Representation matters. A priority queue adds logarithmic operations to ordinary heap-based Dijkstra search.'],
task:'A BFS uses a deque and adjacency lists. It visits V nodes and scans E edges. Which growth estimate describes its work?',options:['O(V × E), because every node must rescan all edges.','O(1), because deque operations are efficient.','O(V + E), because visits and edge scans add together.','Exactly V + E milliseconds on every computer.'],answer:2,
explanations:['Each node scans its own adjacency list, not the entire graph.','Individual queue operations are efficient; the algorithm still visits nodes and edges.','Correct. Each node and edge contributes a bounded amount of traversal work.','Big-O is a growth bound, not a hardware-independent time unit.'],hint:'Count total node visits and total edge inspections separately, then add them.',takeaway:'Data structures and representation determine an algorithm’s growth.'}),
quiz({id:'admissible-compass',chapter:16,title:'A compass that never exaggerates',subtitle:'A* and lower-bound heuristics',
lesson:['A* prioritizes a node using f = g + h: cost already paid (g), plus an estimate of remaining cost (h). A useful heuristic directs exploration toward the goal.', 'An admissible heuristic never overestimates the true remaining minimum cost. A consistent heuristic also satisfies h(u) <= cost(u,v) + h(v) for each edge. With nonnegative costs and a consistent heuristic, standard graph-search A* can avoid reopening closed nodes while retaining optimality.', 'Zero is a valid consistent heuristic for nonnegative edges, reducing A* to Dijkstra. A straight-line distance is appropriate only if edge costs cannot undercut that distance in the same units.'],
task:'Routes are priced in coins, with cheap train tickets unrelated to physical distance. Which heuristic is guaranteed safe from the information given?',options:['Straight-line kilometres used directly as coins.','Twice the guessed remaining fare.','The largest ticket price anywhere in the region.','Zero remaining coins for every node.'],answer:3,
explanations:['The units and lower-bound guarantee are missing; a cheap train can violate it.','An exaggerated estimate can sacrifice the cheapest-path guarantee.','A large unrelated fare can exceed the actual remaining cost.','Correct. Costs are nonnegative, so zero never overestimates, though it offers no directional help.'],hint:'A weak valid lower bound is safer than a plausible estimate with no guarantee.',takeaway:'A heuristic’s guarantees matter more than how intuitive its guess feels.'}),
code({id:'gini-orchard',chapter:17,title:'The orchard’s mixed baskets',subtitle:'Measure class impurity',
lesson:['A decision tree repeatedly splits training examples into groups. Before choosing a split, measure how mixed a group’s labels are. Gini impurity is 1 - sum(p_class²).', 'A pure basket has one class, so impurity is zero. Two equally common classes give 0.5; three equally common classes give 2/3. This is a class-distribution measure, not a model’s test error.', 'Count all classes, including labels you have not named in advance. An empty group has no class proportions; this exercise defines its impurity as zero.'],
example:'labels = ["apple", "apple", "pear"]\n# Gini = 1 - (2/3)**2 - (1/3)**2 = 4/9',
task:'Write gini(labels) for hashable class labels. Return 1 minus the sum of squared class proportions; return 0.0 for an empty list. Support more than two classes.',
starter:'def gini(labels):\n    return 0.0',solution:giniHelper,
checks:check('gini','for labels,want in [([],0),([0,0],0),([0,1],.5),(["a","b","c"],2/3),([0,0,0,1],.375)]:\n    before=labels.copy()\n    assert abs(f(labels)-want)<1e-9, "Use every class proportion and square it."\n    assert labels==before'),
hint:'Build counts, divide each by the total, square those fractions, and subtract their sum from one.',takeaway:'Impurity measures label mixture; it can guide a training split without proving generalization.'}),
code({id:'weighted-split-gain',chapter:17,title:'A fair weighing of branches',subtitle:'Weight child impurity by sample count',
lesson:['A split can produce children of very different sizes. Its remaining impurity is (n_left * gini(left) + n_right * gini(right)) / n_total.', 'Impurity gain is gini(parent) minus that weighted child impurity. Averaging the two child impurities equally would overvalue a tiny pure branch.', 'The parent labels here are exactly left + right. In a fitted tree, gain is a greedy local criterion; it does not by itself choose the best whole tree or guarantee low test error.'],
example:'# Parent impurity .5, children of sizes 1 and 3:\n# Remaining impurity = (1*0 + 3*(4/9)) / 4 = 1/3\n# Gain = .5 - 1/3 = 1/6',
task:'Using the supplied gini helper, write split_gain(left, right). Return parent Gini minus size-weighted child Gini. If both lists are empty return 0.0.',
starter:giniHelper+'\ndef split_gain(left, right):\n    return 0.0',
solution:giniHelper+'\ndef split_gain(left, right):\n    n = len(left) + len(right)\n    if n == 0:\n        return 0.0\n    children = (len(left)*gini(left) + len(right)*gini(right)) / n\n    return gini(left + right) - children',
checks:check('split_gain','assert abs(f([0],[0,1,1])-1/6)<1e-9, "Weight the larger branch more heavily."\nassert abs(f([0,0],[1,1])-.5)<1e-9\nassert abs(f([],[0,1]))<1e-9\nassert f([],[])==0\nassert abs(f([0,1],[0,1]))<1e-9'),
hint:'Use the combined count as the denominator. One empty child leaves the impurity unchanged.',takeaway:'Weight each branch by how many examples it contains.'}),
code({id:'learn-tree-stump',chapter:17,title:'Let the first branch learn',subtitle:'Search candidate numerical splits',
lesson:['A tree stump is a tree with one split. For one numeric feature, candidate thresholds lie halfway between adjacent DISTINCT sorted feature values. Equal values must stay together.', 'For each threshold t, place x <= t on the left and x > t on the right. Compute size-weighted impurity and choose the smallest score. This exercise keeps the smaller threshold when scores tie within 1e-12.', 'Candidate search learns a rule from training examples. This simple implementation scans all rows per candidate, so its worst-case work is quadratic; a larger implementation can update class counts during a sorted sweep.'],
example:'# Distinct feature values [1, 3, 7] give thresholds 2 and 5.\n# Duplicated measurements do not create an extra threshold.',
task:'Write best_threshold(xs, labels) for matching nonempty lists. Search midpoints of distinct sorted xs and minimize weighted Gini. Return the smaller threshold for ties within 1e-12, or None if all xs are equal. Preserve inputs. A gini helper is supplied.',
starter:giniHelper+'\ndef best_threshold(xs, labels):\n    return None',
solution:giniHelper+'\ndef best_threshold(xs, labels):\n    values = sorted(set(xs))\n    best = None\n    best_score = float("inf")\n    for a, b in zip(values, values[1:]):\n        threshold = (a + b) / 2\n        left = [y for x, y in zip(xs, labels) if x <= threshold]\n        right = [y for x, y in zip(xs, labels) if x > threshold]\n        score = (len(left)*gini(left) + len(right)*gini(right)) / len(xs)\n        if score < best_score - 1e-12:\n            best, best_score = threshold, score\n    return best',
checks:check('best_threshold','for xs,ys,want in [([1,2,3,4],[0,0,1,1],2.5),([3,1,2],[0,0,1],1.5),([1,1,3,3],[0,0,1,1],2),([2,2],[0,1],None),([8],[1],None),([1,4,9],[0,0,0],2.5)]:\n    a,b=xs.copy(),ys.copy()\n    assert f(xs,ys)==want, "Use distinct-value midpoints and stable tie-breaking."\n    assert xs==a and ys==b'),
hint:'Sort the distinct feature values, evaluate each adjacent midpoint, and replace the winner only for an improvement greater than 1e-12.',takeaway:'A learned threshold comes from comparing training splits, not guessing a convenient cutoff.'}),
quiz({id:'forest-diversity',chapter:17,title:'A council of different trees',subtitle:'Why ensemble diversity matters',
lesson:['An ensemble combines several models. Bagging fits models on bootstrap samples: sample training rows with replacement. Some examples appear more than once and some are left out.', 'A random forest also considers random feature subsets when splitting. Together these choices reduce similarity between trees. Averaging less-correlated errors can reduce variance compared with one unstable tree.', 'Identical predictions contribute no diversity. More trees cannot repair an unsuitable target, contaminated evaluation data, or every shared bias. Evaluate the ensemble against its individual and simple baselines.'],
task:'Mira copies one fitted tree 100 times and averages their predicted probabilities. What changes?',options:['The average is the original prediction; identical copies add no diversity.','Every error becomes 100 times smaller.','The copies become a random forest automatically.','Averaging proves that the probabilities are calibrated.'],answer:0,
explanations:['Correct. Averaging the same value repeatedly returns that value.','Error reduction depends on the models and error correlations, not the copy count alone.','A random forest requires separately trained, randomized trees.','Calibration needs evidence from predictions and outcomes; copying supplies none.'],hint:'What is the average of the same number repeated many times?',takeaway:'Ensembles benefit from complementary models, not duplicated certainty.'}),
...laterFrontierQuests
];
